import { useCallback, useEffect, useMemo, useRef, useState, type FormEvent } from 'react';
import { ArrowDownLeft, ArrowRight, ArrowUpRight, Bell, Buildings, CaretDown, ChartPieSlice, Check, CheckCircle, Clock, Copy, CreditCard, CurrencyBtc, DotsThree, DownloadSimple, GearSix, HandCoins, Info, Lightning, List, MagnifyingGlass, Plus, Receipt, ShieldCheck, SignOut, SlidersHorizontal, Sparkle, SquaresFour, UsersThree, Wallet, WarningCircle, X } from '@phosphor-icons/react';
import QRCode from 'qrcode';
import '@fontsource-variable/manrope';
import { api, clearTemporaryIdentity, CONNECT_INSTALL_URL, hasTemporaryIdentity, nostrProviderStatus, NostrProviderUnavailableError, nostrSignIn, patch, post, temporaryNostrSignIn, watchNostrProviders, type NostrProviderChoice, type NostrSignInPhase } from './api';
import { Avatar, dateLabel, Dialog, Empty, FlowIcon, fullDate, Progress, ProofReceipt, roleLabel, sats, Status } from './components';
import type { Audit, Expense, Incoming, Invoice, Member, Organization, Snapshot, User, View } from './types';
import { GreyMark } from './Brand';

type Modal = { type: 'request' } | { type: 'wallet' } | { type: 'receive'; invoice?: Invoice } | { type: 'expense'; item: Expense } | { type: 'pay'; item: Expense } | { type: 'member'; member?: Member } | { type: 'workspace' } | { type: 'delete-company' } | { type: 'help' };
const navigation = [{ label: 'Overview' as View, icon: SquaresFour }, { label: 'Requests' as View, icon: Receipt }, { label: 'Transactions' as View, icon: ArrowsIcon }, { label: 'Team' as View, icon: UsersThree }, { label: 'Budgets' as View, icon: ChartPieSlice }, { label: 'Settings' as View, icon: GearSix }];
function ArrowsIcon({ size = 20 }: { size?: number }) { return <ArrowUpRight size={size} />; }
const titles: Record<View, [string, string]> = { Overview: ['Your team. One treasury.', 'A clear view of your company’s Bitcoin and the people behind it.'], Requests: ['Good spending starts here.', 'Review expenses, keep budgets in check, and pay with confidence.'], Transactions: ['Every sat has a story.', 'A readable record of money in, money out, and verified payments.'], Team: ['Built for your people.', 'Give everyone the right access and a clear spending limit.'], Budgets: ['Room to build. Limits to trust.', 'Monthly spending policies that are checked before every approval.'], Settings: ['Make this workspace yours.', 'Manage your company details, connected wallet, and spending policy.'] };
const actionLabel: Record<string, string> = { workspace_created: 'Created the workspace', member_added: 'Added a team member', member_updated: 'Updated member permissions', member_removed: 'Removed member access', policy_updated: 'Updated spending policy', expense_requested: 'Submitted a request', expense_approved: 'Approved a request', expense_rejected: 'Declined a request', payment_started: 'Started a payment', payment_verified: 'Verified a payment', payment_reconciled: 'Reconciled a payment', payment_reconciliation_required: 'Flagged a payment for checking', invoice_created: 'Created a receive invoice', incoming_payment_verified: 'Verified an incoming payment', invoice_expired: 'Closed an expired invoice' };
const budgetPeriodHint = "Budgets follow calendar months, starting on the first day at 00:00 UTC.";
const isTestNetwork = (network?: string) => ['regtest', 'testnet', 'signet'].includes(network?.toLowerCase() ?? '');

export default function App({ onHome }: { onHome?: () => void } = {}) {
  const [data, setData] = useState<Snapshot | null>(null);
  const [organizations, setOrganizations] = useState<Organization[]>([]);
  const [orgId, setOrgId] = useState('');
  const [session, setSession] = useState<User | null>(null);
  const [demoEnabled, setDemoEnabled] = useState(false);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [busy, setBusy] = useState(false);
  const [view, setView] = useState<View>('Overview');
  const [modal, setModal] = useState<Modal | null>(null);
  const [workspaceOpen, setWorkspaceOpen] = useState(false);
  const [profileOpen, setProfileOpen] = useState(false);
  const [notificationsOpen, setNotificationsOpen] = useState(false);
  const [search, setSearch] = useState('');
  const [requestFilter, setRequestFilter] = useState('all');
  const [toast, setToast] = useState('');
  const [temporaryIdentity, setTemporaryIdentity] = useState(hasTemporaryIdentity);
  const workspaceVersion = useRef(0);
  const close = useCallback(() => setModal(null), []);

  const load = useCallback(async (selected = orgId) => {
    const version = ++workspaceVersion.current;
    const list = await api<{ organizations: Organization[] }>('/api/satfamily/organizations');
    if (version !== workspaceVersion.current) return null;
    setOrganizations(list.organizations);
    const id = selected || list.organizations[0]?.id;
    if (!id) { setData(null); setOrgId(''); return null; }
    const snapshot = await api<Snapshot>(`/api/satfamily/organizations/${encodeURIComponent(id)}`);
    if (version !== workspaceVersion.current) return null;
    setData(snapshot); setOrgId(id); setSession(snapshot.currentUser); setError('');
    return snapshot;
  }, [orgId]);

  useEffect(() => {
    let disposed = false;
    const version = ++workspaceVersion.current;
    (async () => {
      try {
        let info = await api<{ user: User | null; demoEnabled: boolean }>('/api/session');
        if (disposed || version !== workspaceVersion.current) return;
        if (!info.user && info.demoEnabled) info = { ...info, ...await post<{ user: User }>('/api/demo/session', { persona: 'owner' }) };
        if (disposed || version !== workspaceVersion.current) return;
        setSession(info.user); setDemoEnabled(info.demoEnabled);
        if (info.user) {
          const list = await api<{ organizations: Organization[] }>('/api/satfamily/organizations');
          if (disposed || version !== workspaceVersion.current) return;
          setOrganizations(list.organizations);
          if (list.organizations[0]) {
            const snapshot = await api<Snapshot>(`/api/satfamily/organizations/${encodeURIComponent(list.organizations[0].id)}`);
            if (disposed || version !== workspaceVersion.current) return;
            setOrgId(snapshot.organization.id); setData(snapshot);
          }
        }
      } catch (failure) { if (!disposed && version === workspaceVersion.current) setError(failure instanceof Error ? failure.message : 'Could not load the workspace.'); }
      finally { if (!disposed) setLoading(false); }
    })();
    return () => { disposed = true; };
  }, []);
  useEffect(() => { if (!toast) return; const timeout = setTimeout(() => setToast(''), 5500); return () => clearTimeout(timeout); }, [toast]);

  const run = async <T,>(fn: () => Promise<T>, message?: string): Promise<T | undefined> => {
    setBusy(true); setError('');
    try { const result = await fn(); if (message) setToast(message); return result; }
    catch (failure) { setError(failure instanceof Error ? failure.message : 'Could not complete this action.'); return undefined; }
    finally { setBusy(false); }
  };
  const switchPersona = async (persona: 'owner' | 'finance' | 'employee') => {
    setProfileOpen(false); close();
    await run(async () => { const info = await post<{ user: User }>('/api/demo/session', { persona }); workspaceVersion.current++; setSession(info.user); await load('preview-baobab'); }, `Previewing ${roleLabel(persona)} access`);
  };
  const currentMember = data?.members.find(member => member.id === data.currentUser.id);
  const canReview = data?.role === 'owner' || data?.role === 'finance';
  const canRequest = data?.role !== 'viewer';
  const ownsCompany = data?.role === 'owner' || organizations.some(org => org.owner_id === session?.id || org.role === 'owner');
  const canCreateCompany = Boolean(session && !session.demo && !ownsCompany);
  const pending = data?.expenses.filter(expense => expense.status === 'pending') ?? [];
  const navigate = (next: View) => { setView(next); setWorkspaceOpen(false); setProfileOpen(false); setNotificationsOpen(false); setSearch(''); setRequestFilter('all'); window.scrollTo({ top: 0, behavior: 'auto' }); };
  const endpoint = (suffix: string) => `/api/satfamily/organizations/${encodeURIComponent(orgId)}${suffix}`;
  const review = async (item: Expense, action: 'approve' | 'reject' | 'pay' | 'reconcile', reason = '') => {
    await run(async () => {
      const result = await post<{ status: string; error?: string }>(endpoint(`/expenses/${encodeURIComponent(item.id)}/${action}`), action === 'reject' ? { reason } : {});
      const fresh = await load();
      const next = fresh?.expenses.find(expense => expense.id === item.id);
      if (next) setModal({ type: 'expense', item: next });
      setToast(result.error ?? (action === 'approve' ? (item.is_fixture ? 'Sample approval recorded. No funds moved.' : 'Approved. The budget is reserved.') : action === 'reject' ? 'Request declined.' : result.status === 'settled' ? 'Payment verified and recorded.' : 'Payment status needs checking.'));
    });
  };
  const copy = async (text: string) => { try { await navigator.clipboard.writeText(text); setToast('Copied to clipboard'); } catch { setToast('Clipboard unavailable. Select the text to copy it.'); } };
  const exportLedger = () => {
    if (!data) return;
    const csv = ['Date,Direction,Reference,Amount sats,Status,Sample,Settlement time,Payment preimage,Wallet connection fingerprint', ...data.expenses.map(item => `${new Date(item.created_at).toISOString()},outgoing,${item.payment_hash},${item.amount_sats},${item.status},${Boolean(item.is_fixture)},${item.settled_at ? new Date(item.settled_at).toISOString() : ''},${item.preimage ?? ''},${item.wallet_fingerprint ?? ''}`), ...data.incoming.map(item => `${new Date(item.created_at).toISOString()},incoming,${item.payment_hash},${item.amount_sats},${item.state},false,${item.settled_at ? new Date(item.settled_at).toISOString() : ''},${item.preimage ?? ''},${item.wallet_fingerprint ?? ''}`)].join('\n');
    const link = document.createElement('a'); const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv;charset=utf-8' })); link.href = url; link.download = 'greyfinance-ledger.csv'; link.click(); URL.revokeObjectURL(url); setToast('Ledger exported');
  };
  const deleteCompany = async (confirmation: string) => run(async () => {
    const targetId = orgId;
    const result = await api<{ deleted: boolean; deletedOrganizationId: string; walletDisconnected: boolean }>(endpoint(''), { method: 'DELETE', body: JSON.stringify({ confirmation }) });
    if (!result.deleted || result.deletedOrganizationId !== targetId) throw new Error('The server could not confirm company deletion. Refresh your workspace before trying again.');
    // The server has confirmed deletion. Clear the removed company even if the
    // following list request fails, while retaining the signed-in identity.
    workspaceVersion.current++;
    close(); setData(null); setOrgId(''); setOrganizations(previous => previous.filter(org => org.id !== targetId));
    navigate('Overview');
    setToast('Company deleted. Your wallet funds remain with your wallet provider.');
    await load('');
    return result;
  });

  return <div className="app-shell">
    <a className="skip-link" href="#main-content">Skip to workspace</a>
    <header className="global-header"><div className="global-header-inner">
      <button className="brand" aria-label="GreyFinance home" onClick={() => onHome ? onHome() : navigate('Overview')}><GreyMark size={36} /><span>greyfinance<span className="brand-dot">.</span></span></button>
      <div className="workspace-control"><button className="workspace-switch" disabled={!session} onClick={() => setWorkspaceOpen(!workspaceOpen)} aria-expanded={workspaceOpen}><span className="workspace-mark"><Buildings size={21} /></span><span className="workspace-name">{data?.organization.name ?? 'Your workspace'}<small>Company account</small></span><CaretDown size={14} /></button>{workspaceOpen && <div className="workspace-menu">{organizations.map(org => <button key={org.id} onClick={() => { setWorkspaceOpen(false); void run(() => load(org.id)); }}><Buildings size={16} /><span>{org.name}</span>{org.id === orgId && <Check size={15} />}</button>)}{canCreateCompany && <button onClick={() => { setWorkspaceOpen(false); setModal({ type: 'workspace' }); }}><Plus size={16} />Create workspace</button>}{ownsCompany && <p className="workspace-limit">You can own one company and join others.</p>}</div>}</div>
      <div className="topbar-actions">{data?.preview && <span className="preview-badge"><span />Preview workspace</span>}<div className="notification-anchor"><button className="icon-button" aria-label={`Notifications: ${pending.length} requests need review`} onClick={() => setNotificationsOpen(!notificationsOpen)}><Bell size={21} />{pending.length > 0 && <span className="notification-dot" />}</button>{notificationsOpen && <div className="notification-menu"><strong>Workspace updates</strong><p>{pending.length ? `${pending.length} request${pending.length === 1 ? '' : 's'} waiting for review.` : 'You’re all caught up.'}</p><button onClick={() => { setNotificationsOpen(false); setView('Requests'); setRequestFilter('pending'); }}>Open approval inbox <ArrowRight size={16} /></button></div>}</div><div className="profile-anchor"><button className="profile-button" disabled={!session || busy} onClick={() => setProfileOpen(!profileOpen)} aria-expanded={profileOpen} aria-label="Account and preview roles"><Avatar name={currentMember?.name ?? 'Your Account'} small /><CaretDown size={12} /></button>{profileOpen && <div className="profile-menu"><strong>{currentMember?.name ?? 'Your account'}</strong><small>{roleLabel(data?.role ?? 'member')}{data?.preview ? ' · local preview' : ''}</small>{demoEnabled && <><span className="menu-label">TRY A TEAM ROLE</span><button onClick={() => void switchPersona('owner')}><Buildings size={16} />Owner {data?.role === 'owner' && <Check size={14} />}</button><button onClick={() => void switchPersona('finance')}><ShieldCheck size={16} />Finance {data?.role === 'finance' && <Check size={14} />}</button><button onClick={() => void switchPersona('employee')}><UsersThree size={16} />Employee {data?.role === 'employee' && <Check size={14} />}</button></>}<button disabled={!session || busy} onClick={() => { setProfileOpen(false); void run(async () => { workspaceVersion.current++; await post('/api/session/logout'); clearTemporaryIdentity(); setTemporaryIdentity(false); setData(null); setSession(null); setOrgId(''); setOrganizations([]); }, 'Signed out'); }}><SignOut size={16} />Sign out</button></div>}</div></div>
    </div></header>
    <div className="product-navigation"><div className="product-nav-inner"><nav aria-label="Workspace navigation">{navigation.map(({ label, icon: Icon }) => <button key={label} className={`nav-link ${view === label ? 'active' : ''}`} onClick={() => navigate(label)} aria-label={label} aria-current={view === label ? 'page' : undefined}><Icon size={19} /><span className="nav-label-desktop">{label}</span><span className="nav-label-mobile">{label === 'Transactions' ? 'Activity' : label}</span>{label === 'Requests' && pending.length > 0 && <span className="nav-count" aria-hidden="true">{pending.length}</span>}</button>)}</nav><button className="help-link" onClick={() => setModal({ type: 'help' })}><Info size={18} />How it works</button></div></div>
    <div className="main-shell">
    <main className="page-content" id="main-content" tabIndex={-1}><div className="page-heading"><div><div className="eyebrow"><span className="eyebrow-line" />{data?.role === 'employee' ? 'YOUR COMPANY ACCOUNT' : 'COMPANY WORKSPACE'}</div><h1>{titles[view][0]}</h1><p>{titles[view][1]}</p></div>{data && canRequest && <button className="button primary" onClick={() => setModal({ type: 'request' })}><Plus size={18} weight="bold" />New request</button>}</div>
      {error && <div className="alert error-alert" role="alert"><WarningCircle size={20} /><span>{error}</span><button className="icon-button" onClick={() => setError('')} aria-label="Dismiss error"><X size={17} /></button></div>}
      {temporaryIdentity && <div className="alert temporary-identity-notice"><ShieldCheck size={20} /><span><strong>Temporary Nostr identity</strong>Your signing key exists only in this tab’s memory. Use Connect or your existing Nostr signer for ongoing company access. No wallet is connected automatically.</span></div>}
      {loading ? <div className="loading-grid" aria-label="Loading workspace"><div /><div /><div /><div /></div> : !data ? <div className="onboarding">
        <div className="onboarding-art"><Buildings size={60} weight="duotone" /><span><Lightning size={22} weight="fill" /></span></div>
        <h2>A company account with a human side.</h2><p>Create a shared workspace for your team, connect your Lightning wallet, and give every expense a clear approval trail.</p>
        {session ? <div className="onboarding-actions">{canCreateCompany && <button className="button primary" onClick={() => setModal({ type: 'workspace' })}><Plus size={17} />Create your workspace</button>}</div> : <>
          <NostrSignInPanel busy={busy} onBusyChange={setBusy} onAuthenticated={async () => {
            workspaceVersion.current++; setTemporaryIdentity(false); setError('');
            try { const info = await api<{ user: User | null }>('/api/session'); if (!info.user) throw new Error('The server could not confirm your sign-in. Please retry with a fresh signature.'); setSession(info.user); await load(''); setToast('Signed in with Nostr'); }
            catch (failure) { setError(failure instanceof Error ? failure.message : 'Could not load your signed-in workspace.'); throw failure; }
          }} />
          <details className="temporary-sign-in-trial"><summary>Trying the product with a temporary identity?</summary><p>This trial key stays only in this tab’s memory. Closing the tab loses its signing key. Use Connect or your existing signer for an ongoing company account.</p><button className="button secondary temporary-sign-in" disabled={busy} onClick={() => void run(async () => { await temporaryNostrSignIn(); workspaceVersion.current++; setTemporaryIdentity(true); const info = await api<{ user: User }>('/api/session'); setSession(info.user); await load(''); }, 'Signed in with a temporary Nostr identity')}>Try with a temporary Nostr identity <ArrowRight size={17} /></button></details>
        </>}
        {demoEnabled && <div className="onboarding-actions"><button className="button secondary" disabled={busy} onClick={() => void switchPersona('owner')}>Open preview workspace</button></div>}
        <div className="onboarding-facts"><span><ShieldCheck size={18} />Company-controlled wallet</span><span><UsersThree size={18} />Clear team permissions</span><span><Receipt size={18} />Verified payment records</span></div>
      </div> : <>
        {data.preview && <div className="preview-notice"><Sparkle size={16} /><span>{isTestNetwork(data.wallet.network) ? 'Test workspace · wallet payments run on a private Bitcoin test network. Sample requests never move funds. Test sats have no live Bitcoin value.' : 'This workspace includes sample data. Sample requests never move funds. Connect a wallet and use a real invoice to test payment.'}</span><button onClick={() => setModal({ type: 'wallet' })}>Wallet settings <ArrowRight size={14} /></button></div>}
        {data.wallet.error && <div className="alert wallet-unavailable" role="status"><WarningCircle size={20} /><span>{data.wallet.error} Your saved records are still available.</span><button className="text-button" disabled={busy} onClick={() => void run(() => load())}>Retry wallet status <ArrowRight size={15} /></button></div>}{view === 'Overview' && <Overview data={data} canReview={Boolean(canReview)} onReceive={() => setModal({ type: 'receive' })} onWallet={() => setModal({ type: 'wallet' })} onRequest={() => setModal({ type: 'request' })} onMember={() => setModal({ type: 'member' })} onExpense={item => setModal({ type: 'expense', item })} onView={navigate} />}
        {view === 'Requests' && <Requests data={data} search={search} onSearch={setSearch} filter={requestFilter} onFilter={setRequestFilter} onExpense={item => setModal({ type: 'expense', item })} onRequest={() => setModal({ type: 'request' })} />}
        {view === 'Transactions' && <Transactions data={data} onExpense={item => setModal({ type: 'expense', item })} onInvoice={invoice => setModal({ type: 'receive', invoice })} onExport={exportLedger} />}
        {view === 'Team' && <Team data={data} onAdd={() => setModal({ type: 'member' })} onEdit={member => setModal({ type: 'member', member })} />}
        {view === 'Budgets' && <Budgets data={data} onSettings={() => navigate('Settings')} />}
        {view === 'Settings' && <Settings key={data.organization.id} data={data} busy={busy} onWallet={() => setModal({ type: 'wallet' })} onSave={input => run(async () => { await patch(endpoint(''), input); await load(); }, 'Workspace settings saved')} onExport={exportLedger} onDelete={() => { setError(''); setModal({ type: 'delete-company' }); }} />}
      </>}
      <footer className="page-footer"><span><CurrencyBtc size={14} />Bitcoin for the way teams work.</span><button onClick={() => setModal({ type: 'help' })}>How GreyFinance works <ArrowUpRight size={13} /></button></footer>
    </main></div>
    {toast && modal?.type !== 'delete-company' && <div className="toast" role="status"><CheckCircle size={20} weight="fill" /><span>{toast}</span><button className="icon-button" onClick={() => setToast('')} aria-label="Dismiss notification"><X size={16} /></button></div>}
    {modal && modal.type !== 'delete-company' && error && <div className="toast error-toast" role="alert"><WarningCircle size={20} /><span>{error}</span><button className="icon-button" onClick={() => setError('')} aria-label="Dismiss form error"><X size={16} /></button></div>}
    {modal?.type === 'delete-company' && data && data.role === 'owner' && !data.preview && <DeleteCompanyDialog key={data.organization.id} name={data.organization.name} busy={busy} error={error} onClose={close} onExport={exportLedger} onSubmit={deleteCompany} />}
    {modal?.type === 'request' && data && <RequestDialog preview={data.preview} limit={data.organization.request_limit_sats} busy={busy} onClose={close} onSubmit={input => run(async () => { const result = await post<{ isFixture: boolean }>(endpoint('/expenses'), input); await load(); close(); setToast(result.isFixture ? 'Sample request submitted. Switch to Finance to review it.' : 'Request submitted for approval.'); })} />}
    {modal?.type === 'wallet' && <WalletDialog connected={Boolean(data?.wallet.connected)} network={data?.wallet.network} localLab={Boolean(data?.preview && demoEnabled && data.role === 'owner')} isOwner={!data || data.role === 'owner'} busy={busy} onClose={close} onConnect={uri => run(async () => { await post('/api/wallet/connect', { connectionUri: uri }); if (orgId) await load(); close(); }, 'Company wallet connected')} onTestWallet={() => run(async () => { await post('/api/demo/wallet', { wallet: 'alice' }); if (orgId) await load(); close(); }, 'Lightning test wallet connected. Test sats have no live Bitcoin value.')} onDisconnect={() => run(async () => { await api('/api/wallet', { method: 'DELETE' }); if (orgId) await load(); close(); }, 'Wallet disconnected')} />}
    {modal?.type === 'receive' && data && <ReceiveDialog initial={modal.invoice} canReceive={Boolean(canReview)} walletConnected={data.wallet.connected} busy={busy} onClose={close} onWallet={() => setModal({ type: 'wallet' })} onCopy={copy} onCreate={input => run(async () => { const invoice = await post<Invoice>(endpoint('/invoices'), input); await load(); return invoice; }, 'Receive invoice created')} onVerify={hash => api<Invoice>(endpoint(`/invoices/${encodeURIComponent(hash)}`))} onSettled={() => void load()} />}
    {modal?.type === 'expense' && data && <ExpenseDialog item={modal.item} data={data} busy={busy} onClose={close} onCopy={copy} onAction={(action, reason) => void review(modal.item, action, reason)} onPay={() => setModal({ type: 'pay', item: modal.item })} onFinance={() => void switchPersona('finance')} />}
    {modal?.type === 'pay' && <Dialog title="Confirm company payment" description="This sends Bitcoin from the connected company wallet." onClose={close}><div className="payment-confirm"><span className="confirm-icon"><Lightning size={32} weight="fill" /></span><h3>{sats(modal.item.amount_sats)} <span>sats</span></h3><p>{modal.item.title}</p><div className="detail-grid"><span>Requester<strong>{modal.item.requester_name ?? 'Team member'}</strong></span><span>Approved by<strong>{modal.item.approver_name ?? 'Finance member'}</strong></span></div><p className="helper">Lightning payments cannot be reversed. The wallet’s fees and permissions still apply.</p><button className="button primary full-width" disabled={busy} onClick={() => void review(modal.item, 'pay')}><Lightning size={18} />{busy ? 'Checking wallet…' : `Pay ${sats(modal.item.amount_sats)} sats`}</button></div></Dialog>}
    {modal?.type === 'member' && data && <MemberDialog member={modal.member} isOwner={data.role === 'owner'} busy={busy} onClose={close} onSubmit={input => run(async () => { if (modal.member) await patch(endpoint(`/members/${encodeURIComponent(modal.member.id)}`), input); else await post(endpoint('/members'), input); await load(); close(); }, modal.member ? 'Member permissions updated' : 'Member access added. They can sign in with their Nostr identity.')} />}
    {modal?.type === 'workspace' && canCreateCompany && <WorkspaceDialog busy={busy} onClose={close} onSubmit={input => run(async () => { const result = await post<{ id: string }>('/api/satfamily/organizations', input); await load(result.id); close(); }, 'Your workspace is ready')} />}
    {modal?.type === 'help' && <Dialog title="A clearer way to spend together." description="Three steps from request to verified payment." onClose={close}><div className="help-steps"><div><span>01</span><section><h3>Connect your company wallet</h3><p>The owner links a Lightning wallet using delegated NWC permissions. Never paste a seed phrase or a wallet master key.</p></section></div><div><span>02</span><section><h3>Request, then review</h3><p>A member submits an invoice. A different owner or finance member reviews it. Monthly limits are checked before the budget is reserved.</p></section></div><div><span>03</span><section><h3>Pay once. Verify it.</h3><p>Finance confirms the payment. GreyFinance checks wallet proof and keeps a receipt. If the result is unclear, it holds the budget and checks status before another action.</p></section></div></div><div className="alert"><ShieldCheck size={21} /><span>These approvals are enforced by GreyFinance. Also cap spending and permissions at your wallet provider; this MVP does not provide on-chain multisignature.</span></div>{data?.preview && <p className="helper">Use the profile menu to try Owner, Finance, and Employee views. Sample payments are clearly marked and never sent to a wallet.</p>}</Dialog>}
  </div>;
}

function signInFailure(failure: unknown, provider: 'connect' | 'nip07') {
  const message = failure instanceof Error ? failure.message : typeof failure === 'string' ? failure : 'Sign-in could not finish. Please try again.';
  let code: unknown;
  try { code = typeof failure === 'object' && failure !== null ? (failure as { code?: unknown }).code : undefined; } catch { /* Keep the safe fallback message. */ }
  if (code === 4001 || (typeof code === 'string' && ['USER_REJECTED', 'REQUEST_DECLINED', 'REQUEST_REJECTED', 'ACTION_REJECTED'].includes(code))) return 'Sign-in was declined. Retry when you are ready to approve a fresh signature request.';
  if (provider === 'connect') {
    if (code === 'WALLET_LOCKED') return 'Connect is locked. Open it from your browser toolbar, unlock your wallet, then retry sign-in.';
    if (code === 'REQUEST_EXPIRED') return 'The Connect sign-in request expired. Return here and retry to review a fresh signature request.';
    if (code === 'SITE_DISCONNECTED' || code === 'SITE_PERMISSION') return 'Connect no longer has access to this website. In Connect, open Connections, enable the current website and choose Allow in Chrome. Then retry sign-in.';
    if (code === 'TOO_MANY_REQUESTS') return 'Finish or decline the open request in Connect before retrying sign-in.';
    if (code === 'WALLET_UNAVAILABLE') return 'Connect could not respond. Open it from your browser toolbar, unlock your wallet and check that this website is enabled, then retry.';
  }
  return message;
}

function NostrSignInPanel({ busy, onBusyChange, onAuthenticated }: { busy: boolean; onBusyChange(value: boolean): void; onAuthenticated(): Promise<void> }) {
  const [providers, setProviders] = useState(nostrProviderStatus);
  const [guideOpen, setGuideOpen] = useState(() => !nostrProviderStatus().connect);
  const [checked, setChecked] = useState(false);
  const [phase, setPhase] = useState<NostrSignInPhase | null>(null);
  const [activeProvider, setActiveProvider] = useState<'connect' | 'nip07' | null>(null);
  const [feedback, setFeedback] = useState<{ message: string; provider: 'connect' | 'nip07'; unavailable: boolean } | null>(null);
  const attempt = useRef<AbortController | null>(null);
  const origin = typeof window === 'undefined' ? 'this website' : window.location.origin;
  const refresh = useCallback(() => {
    const next = nostrProviderStatus();
    setProviders(previous => previous.connect === next.connect && previous.nip07 === next.nip07 ? previous : next);
    setFeedback(previous => previous?.unavailable && next[previous.provider] ? null : previous);
  }, []);
  useEffect(() => { const stop = watchNostrProviders(refresh); refresh(); return stop; }, [refresh]);
  useEffect(() => () => attempt.current?.abort(), []);

  async function signIn(provider: Exclude<NostrProviderChoice, 'auto'>) {
    if (attempt.current || busy) return;
    const controller = new AbortController(); attempt.current = controller;
    setFeedback(null); setActiveProvider(provider); setPhase('checking'); onBusyChange(true);
    try {
      await nostrSignIn(provider, { signal: controller.signal, onPhase: value => { if (!controller.signal.aborted) setPhase(value); } });
      if (!controller.signal.aborted) await onAuthenticated();
    } catch (failure) {
      if (!controller.signal.aborted) {
        setFeedback({ message: signInFailure(failure, provider), provider, unavailable: failure instanceof NostrProviderUnavailableError });
        if (provider === 'connect') setGuideOpen(true);
        refresh();
      }
    } finally {
      if (attempt.current === controller) { attempt.current = null; setPhase(null); setActiveProvider(null); onBusyChange(false); }
    }
  }

  const phaseLabel = phase === 'checking' ? 'Checking your signer…' : phase === 'approval' ? 'Waiting for your approval…' : 'Confirming your sign-in…';
  return <section className="sign-in-panel" aria-label="Nostr sign-in">
    <div className={'sign-in-status ' + (providers.connect || providers.nip07 ? 'signer-ready' : '')} role="status" aria-live="polite" aria-atomic="true">
      <span className="sign-in-status-icon">{phase ? <Clock size={21} /> : providers.connect || providers.nip07 ? <CheckCircle size={21} /> : <ShieldCheck size={21} />}</span>
      <div><strong>{phase ? phaseLabel : providers.connect ? 'Connect is available for this website' : providers.nip07 ? 'Your Nostr signer is available' : checked ? 'Connect is still unavailable here' : 'Enable Connect for this website'}</strong><p>{phase === 'approval' ? `Open ${activeProvider === 'connect' ? 'Connect' : 'your signer'} and review this website’s signature request.` : phase === 'verifying' ? 'GreyFinance is verifying the signed request with the server.' : phase === 'checking' ? 'Checking for a signer enabled on the current website.' : providers.connect ? 'Sign in with the Nostr identity you already keep in Connect.' : providers.nip07 ? 'Use your existing signer below, or enable Connect with the steps here.' : 'Connect appears here after you enable the current website.'}</p></div>
    </div>
    <div className="sign-in-origin"><span>Current website</span><code>{origin}</code></div>
    <div className="sign-in-actions">
      <button className="button primary" disabled={busy || Boolean(phase)} onClick={() => void signIn('connect')}>{phase && activeProvider === 'connect' ? phaseLabel : feedback?.provider === 'connect' ? 'Retry Connect sign-in' : 'Sign in with Connect'}<ArrowRight size={17} /></button>
      {providers.nip07 && <button className="button secondary" disabled={busy || Boolean(phase)} onClick={() => void signIn('nip07')}>{phase && activeProvider === 'nip07' ? phaseLabel : 'Use another Nostr signer'}<ArrowUpRight size={17} /></button>}
    </div>
    {feedback && <div className="sign-in-error" role="alert"><WarningCircle size={18} /><span>{feedback.message}</span></div>}
    <p className="sign-in-scope">Sign-in uses your Nostr identity. The company Lightning wallet connects separately through NWC in Wallet settings.</p>
    <details className="sign-in-guide" open={guideOpen} onToggle={event => setGuideOpen(event.currentTarget.open)}>
      <summary><span><Info size={17} />Enable Connect on this website</span><CaretDown size={16} /></summary>
      <ol><li><span>1</span><div><strong>Open and unlock Connect.</strong><p>Use the Connect icon in your desktop browser toolbar and unlock your wallet.</p></div></li><li><span>2</span><div><strong>Enable the current website.</strong><p>In Connect, open <b>Connections</b> and choose <b>Enable for current website</b>. Check that it shows <code>{origin}</code>.</p></div></li><li><span>3</span><div><strong>Allow access, then retry.</strong><p>Choose <b>Allow</b> in Chrome’s website-permission prompt. Return to this tab and retry sign-in.</p></div></li></ol>
      <div className="sign-in-guide-actions"><button className="button secondary" disabled={busy || Boolean(phase)} onClick={() => { refresh(); setChecked(true); }}>Check again<ArrowRight size={16} /></button><a href={CONNECT_INSTALL_URL} target="_blank" rel="noopener noreferrer">Need Connect? Installation guide<ArrowUpRight size={15} /></a></div>
    </details>
  </section>;
}

function Overview({ data, canReview, onReceive, onWallet, onRequest, onMember, onExpense, onView }: { data: Snapshot; canReview: boolean; onReceive(): void; onWallet(): void; onRequest(): void; onMember(): void; onExpense(item: Expense): void; onView(view: View): void }) {
  const pending = data.expenses.filter(item => item.status === 'pending');
  const paid = data.expenses.filter(item => item.status === 'settled' && !item.is_fixture && (item.settled_at ?? item.updated_at) >= data.budgets.periodStart);
  const samplePaid = data.expenses.filter(item => item.status === 'sample_paid' && item.created_at >= data.budgets.periodStart).reduce((sum, item) => sum + item.amount_sats, 0);
  const paidAmount = paid.reduce((sum, item) => sum + item.amount_sats, 0);
  const incoming = data.incoming.filter(item => item.state === 'settled' && (item.settled_at ?? item.created_at) >= data.budgets.periodStart).reduce((sum, item) => sum + item.amount_sats, 0);
  const employee = data.role === 'employee';
  const balance = employee ? data.budgets.memberLimitSats - data.budgets.memberUsedSats : data.wallet.balanceSats ?? (data.preview && !data.wallet.connected ? 428_500 : null);
  const budgetAmount = employee ? data.budgets.memberUsedSats : data.budgets.companyUsedSats;
  const budgetLimit = employee ? data.budgets.memberLimitSats : data.organization.budget_sats;
  return <><div className="overview-top"><section className="treasury-card"><div className="treasury-top"><span><Wallet size={18} />{employee ? 'My spending allowance' : data.wallet.connected ? 'Company wallet' : 'Treasury overview'}</span><span className="treasury-tag"><span />{employee ? 'Monthly limit' : isTestNetwork(data.wallet.network) ? 'Test wallet' : data.wallet.connected ? 'Connected' : data.preview ? 'Sample balance' : 'Not connected'}</span></div><div className="balance-value">{balance === null ? '—' : sats(balance)}<span>sats</span></div><p className="balance-caption">{employee ? 'Remaining allowance after approved expenses' : isTestNetwork(data.wallet.network) ? 'Test sats · private Bitcoin test network' : data.wallet.connected ? 'Available in your connected wallet' : data.preview ? 'Illustrative balance · connect your wallet for live funds' : 'Connect a wallet to see your company balance'}</p><div className="treasury-actions"><button onClick={employee ? onRequest : data.wallet.connected ? onReceive : onWallet}>{employee ? <Plus size={18} /> : <ArrowDownLeft size={18} />}{employee ? 'New expense' : 'Receive'}</button><button onClick={employee ? () => onView('Requests') : onRequest}><ArrowUpRight size={18} />{employee ? 'My requests' : 'Request payment'}</button></div><div className="treasury-bottom"><span><CurrencyBtc size={16} />{employee ? 'MONTHLY EMPLOYEE ALLOWANCE' : 'LIGHTNING TREASURY'}</span><button aria-label="Open company wallet settings" onClick={onWallet}><SlidersHorizontal size={19} /></button></div><svg className="treasury-art" width="192" height="192" viewBox="0 0 192 192" aria-hidden="true"><circle cx="96" cy="96" r="82" /><circle cx="96" cy="96" r="61" /><circle cx="96" cy="96" r="40" /><path d="M96 8v32M96 152v32M8 96h32M152 96h32M34 34l23 23M135 135l23 23M34 158l23-23M135 57l23-23" /><path className="art-bolt" d="m105 62-32 38h23l-8 31 33-39H99z" /></svg></section>
      <section className="summary-card"><div className="summary-title"><span className="section-kicker">THIS MONTH</span><span className="month-chip">{new Intl.DateTimeFormat('en', { month: 'short', year: 'numeric', timeZone: 'UTC' }).format(data.budgets.periodStart)}</span></div><div className="summary-metric"><span className="metric-icon copper"><ArrowUpRight size={19} /></span><div><p>Verified outgoing payments</p><strong>{sats(paidAmount)} <small>sats</small></strong>{data.preview && samplePaid > 0 && <small className="sample-total">{sats(samplePaid)} sats in sample history</small>}</div></div><div className="summary-metric"><span className="metric-icon green"><ArrowDownLeft size={19} /></span><div><p>Verified incoming payments</p><strong>{sats(incoming)} <small>sats</small></strong></div></div><div className="summary-separator" /><div className="summary-foot"><span><span className="tiny-dot amber" />{pending.length} awaiting approval</span><button onClick={() => onView('Transactions')} aria-label="View transactions"><ArrowUpRight size={18} /></button></div></section>
      <section className="budget-overview"><div className="section-title"><h2>Keep spending intentional</h2><span className="leaf-symbol"><ChartPieSlice size={24} weight="duotone" /></span></div><p>{employee ? 'Your monthly spending limit' : 'Your monthly company budget'}</p><div className="budget-amount"><strong>{sats(budgetLimit)}</strong><span>sats</span></div><Progress value={budgetAmount} maximum={budgetLimit} label="Monthly approved and verified spending" /><div className="budget-split"><span><strong>{sats(budgetAmount)}</strong> committed</span><span>{Math.round(budgetAmount / budgetLimit * 100)}%</span></div><button className="text-button" onClick={() => onView('Budgets')}>View team budgets <ArrowRight size={16} /></button></section></div>
    <div className="overview-middle"><section className="panel approval-panel"><div className="panel-heading"><div><h2>Approval inbox <span className="heading-count">{pending.length}</span></h2><p>{canReview ? 'A quick review keeps your team moving.' : 'Your submitted requests and their next step.'}</p></div><button className="text-button" onClick={() => onView('Requests')}>View all <ArrowRight size={15} /></button></div>{pending.length ? <div className="approval-list">{pending.slice(0, 3).map((item, index) => <button className="approval-row" key={item.id} onClick={() => onExpense(item)}><Avatar name={item.requester_name ?? 'Team member'} index={index} /><span className="approval-copy"><strong>{item.title}</strong><small>{item.requester_name} <span>·</span> {item.category}{item.is_fixture ? ' · sample' : ''}</small></span><span className="approval-amount">{sats(item.amount_sats)}<small>sats</small></span><span className="row-chevron"><ArrowRight size={17} /></span></button>)}</div> : <Empty icon={<CheckCircle size={28} />} title="All clear for now" copy="New expense requests will appear here when your team submits them." />}</section>
    <section className="next-card"><span className="next-kicker"><Sparkle size={15} />A GOOD NEXT STEP</span><h2>A workspace that works<br />for everyone.</h2><p>A little setup goes a long way.</p><button className="setup-step" onClick={onWallet}><span className={`setup-check ${data.wallet.connected ? 'complete' : ''}`}>{data.wallet.connected ? <Check size={13} weight="bold" /> : '1'}</span><span>Connect company wallet<small>{data.wallet.connected ? 'Ready for real Lightning payments' : 'Bring your company’s Lightning wallet'}</small></span><ArrowRight size={16} /></button><button className="setup-step" onClick={data.role === 'owner' ? onMember : () => onView('Team')}><span className={`setup-check ${data.members.length > 1 ? 'complete' : ''}`}>{data.members.length > 1 ? <Check size={13} weight="bold" /> : '2'}</span><span>Bring your team together<small>{employee ? 'Employee · requests and personal limits' : `${data.members.filter(item => item.active).length} members in this workspace`}</small></span><ArrowRight size={16} /></button><button className="setup-step" onClick={() => onView('Budgets')}><span className="setup-check complete"><Check size={13} weight="bold" /></span><span>Set a clear spending policy<small>{sats(data.organization.request_limit_sats)} sats per request</small></span><ArrowRight size={16} /></button></section></div>
    <section className="panel"><div className="panel-heading"><div><h2>Recent activity</h2><p>Payments and requests, in one clear record.</p></div><button className="text-button" onClick={() => onView('Transactions')}>Full ledger <ArrowRight size={15} /></button></div><ExpenseTable items={data.expenses.slice(0, 4)} onExpense={onExpense} /></section></>;
}

function ExpenseTable({ items, onExpense }: { items: Expense[]; onExpense(item: Expense): void }) {
  return items.length ? <div className="table-wrap"><table className="expense-table"><thead><tr><th>Expense</th><th>Requested by</th><th>Amount</th><th>Status</th><th aria-label="Details" /></tr></thead><tbody>{items.map((item, index) => <tr key={item.id}><td><button className="expense-name" onClick={() => onExpense(item)}><span className={`category-icon category-${item.category.toLowerCase()}`}><Receipt size={19} /></span><span><strong>{item.title}</strong><small>{item.category} <span>·</span> {dateLabel(item.created_at)}</small></span></button></td><td><span className="member-cell"><Avatar name={item.requester_name ?? 'Team member'} small index={index} />{item.requester_name ?? 'Team member'}</span></td><td className="amount-cell">{sats(item.amount_sats)} <small>sats</small></td><td><Status state={item.status} sample={Boolean(item.is_fixture)} /></td><td><button className="icon-button" onClick={() => onExpense(item)} aria-label={`View ${item.title}`}><DotsThree size={22} weight="bold" /></button></td></tr>)}</tbody></table></div> : <Empty icon={<Receipt size={28} />} title="Nothing here yet" copy="Your team’s expense requests will appear in this record." />;
}
function Requests({ data, search, onSearch, filter, onFilter, onExpense, onRequest }: { data: Snapshot; search: string; onSearch(value: string): void; filter: string; onFilter(value: string): void; onExpense(item: Expense): void; onRequest(): void }) {
  const filters = [['all', 'All requests'], ['pending', 'Needs review'], ['approved', 'Approved'], ['settled', 'Paid'], ['rejected', 'Declined'], ['unknown', 'Needs checking']];
  const items = data.expenses.filter(item => (filter === 'all' || item.status === filter || (filter === 'settled' && item.status === 'sample_paid')) && `${item.title} ${item.requester_name} ${item.category}`.toLowerCase().includes(search.toLowerCase()));
  return <section className="panel requests-panel"><div className="list-toolbar"><div className="filter-tabs" role="tablist" aria-label="Request status">{filters.map(([value, label]) => <button role="tab" aria-selected={filter === value} className={filter === value ? 'active' : ''} key={value} onClick={() => onFilter(value)}>{label}{value === 'pending' && <span>{data.expenses.filter(item => item.status === 'pending').length}</span>}</button>)}</div><label className="search-field"><MagnifyingGlass size={18} /><input type="search" placeholder="Search requests" aria-label="Search expense requests" value={search} onChange={event => onSearch(event.target.value)} /></label></div>{items.length ? <ExpenseTable items={items} onExpense={onExpense} /> : <Empty icon={<Receipt size={29} />} title={search ? 'No matching requests' : 'No requests in this view'} copy={search ? 'Try a different name, category, or expense title.' : 'Submit an expense invoice and your team can review it here.'} action={data.role !== 'viewer' ? <button className="button secondary" onClick={onRequest}><Plus size={16} />New request</button> : undefined} />}<div className="list-footer"><span>{items.length} request{items.length === 1 ? '' : 's'}</span><span><ShieldCheck size={14} />Independent approvals required</span></div></section>;
}
function Transactions({ data, onExpense, onInvoice, onExport }: { data: Snapshot; onExpense(item: Expense): void; onInvoice(item: Invoice): void; onExport(): void }) {
  const [tab, setTab] = useState('all');
  const outgoing = data.expenses.filter(item => ['settled', 'sample_paid', 'paying', 'unknown', 'approved'].includes(item.status));
  const toInvoice = (item: Incoming): Invoice => ({ paymentHash: item.payment_hash, amountSats: item.amount_sats, bolt11: item.bolt11, description: item.description, expiresAt: item.expires_at, state: item.state as Invoice['state'], settledAt: item.settled_at ?? undefined, preimage: item.preimage, walletFingerprint: item.wallet_fingerprint });
  return <><div className="ledger-stats"><div><span><ArrowDownLeft size={18} />Verified received</span><strong>{sats(data.incoming.filter(item => item.state === 'settled').reduce((sum, item) => sum + item.amount_sats, 0))}<small>sats</small></strong></div><div><span><ArrowUpRight size={18} />Verified paid</span><strong>{sats(outgoing.filter(item => !item.is_fixture && item.status === 'settled').reduce((sum, item) => sum + item.amount_sats, 0))}<small>sats</small></strong></div><div><span><Clock size={18} />Reserved for payment</span><strong>{sats(outgoing.filter(item => !item.is_fixture && ['approved', 'paying', 'unknown'].includes(item.status)).reduce((sum, item) => sum + item.amount_sats, 0))}<small>sats</small></strong></div></div><section className="panel"><div className="list-toolbar"><div className="filter-tabs" role="tablist" aria-label="Transaction direction">{[['all', 'All activity'], ['outgoing', 'Outgoing'], ['incoming', 'Incoming']].map(([value, label]) => <button key={value} role="tab" aria-selected={tab === value} className={tab === value ? 'active' : ''} onClick={() => setTab(value)}>{label}</button>)}</div><button className="button secondary compact" onClick={onExport}><DownloadSimple size={16} />Export CSV</button></div>{tab !== 'incoming' && outgoing.length > 0 && <ExpenseTable items={outgoing} onExpense={onExpense} />}{tab !== 'outgoing' && data.incoming.length > 0 && <div className="incoming-list">{data.incoming.map(item => <button key={item.payment_hash} className="incoming-row" onClick={() => onInvoice(toInvoice(item))}><FlowIcon incoming /><span><strong>{item.description}</strong><small>Receive invoice · {dateLabel(item.created_at)}</small></span><strong>{sats(item.amount_sats)} <small>sats</small></strong><Status state={item.state} label={item.state === 'pending' ? 'Awaiting payment' : undefined} /><ArrowRight size={17} /></button>)}</div>}{(tab === 'incoming' ? !data.incoming.length : tab === 'outgoing' ? !outgoing.length : !outgoing.length && !data.incoming.length) && <Empty icon={<HandCoins size={30} />} title="Your payment record starts here" copy="Approved expense payments and company receive invoices will appear here. Verified totals include only real wallet-confirmed payments." />}<div className="list-footer"><span>Sample rows are explicitly marked.</span><span><ShieldCheck size={14} />Payment states verified with the wallet</span></div></section><Activity items={data.activity} /></>;
}
function Activity({ items }: { items: Audit[] }) {
  return <section className="panel activity-panel"><div className="panel-heading"><div><h2>Workspace audit trail</h2><p>Who changed what, and when.</p></div><ShieldCheck size={21} /></div>{items.length ? <div className="audit-list">{items.slice(0, 12).map(item => <div key={item.id}><span className="audit-dot" /><span><strong>{item.actor_name ?? (item.actor_id === 'system' ? 'GreyFinance' : 'Team member')}</strong> {actionLabel[item.action]?.toLowerCase() ?? item.action}<small>{item.note || 'Workspace action recorded'}</small></span><time>{fullDate(item.created_at)}</time></div>)}</div> : <Empty icon={<ShieldCheck size={27} />} title="No workspace events yet" copy="Actions are recorded as your team starts using GreyFinance." />}</section>;
}
function Team({ data, onAdd, onEdit }: { data: Snapshot; onAdd(): void; onEdit(item: Member): void }) {
  return <><div className="team-intro"><div className="stacked-avatars">{data.members.filter(member => member.active).slice(0, 4).map((member, index) => <Avatar key={member.id} name={member.name} index={index} />)}</div><span><strong>{data.members.filter(member => member.active).length} people, one company workspace.</strong><small>Owners manage access. Finance approves. Employees request.</small></span>{data.role === 'owner' && <button className="button primary" onClick={onAdd}><Plus size={17} />Add member</button>}</div><section className="panel team-panel"><div className="team-header"><span>Member</span><span>Role</span><span>Monthly limit</span><span>Access</span><span /></div>{data.members.map((member, index) => <div key={member.id} className={`team-row ${member.active ? '' : 'inactive'}`}><div className="team-member"><Avatar name={member.name} index={index} /><span><strong>{member.name}</strong><small>{member.id === data.currentUser.id ? 'You' : member.pubkey ? `${member.pubkey.slice(0, 10)}…${member.pubkey.slice(-6)}` : 'Preview identity'}</small></span></div><span className={`role-chip role-${member.role}`}><ShieldCheck size={13} />{roleLabel(member.role)}</span><span className="member-limit">{sats(member.periodLimitSats)} <small>sats</small></span><span className={`access-chip ${member.active ? '' : 'disabled'}`}><span />{member.active ? 'Active' : 'Removed'}</span>{data.role === 'owner' && member.role !== 'owner' ? <button className="icon-button" aria-label={`Edit ${member.name} permissions`} onClick={() => onEdit(member)}><DotsThree size={22} weight="bold" /></button> : <span />}</div>)}</section><div className="role-guide">{[['owner', 'Owner', 'Company settings, wallet connection, team access, and independent expense approvals.'], ['finance', 'Finance', 'Review requests, pay approved expenses, receive payments, and read company records.'], ['employee', 'Employee', 'Submit expense requests and track their own approvals and monthly spending.'], ['viewer', 'Viewer', 'Read company records without changing permissions or moving funds.']].map(([role, title, copy]) => <section key={role}><span className={`role-chip role-${role}`}>{title}</span><p>{copy}</p></section>)}</div></>;
}
function Budgets({ data, onSettings }: { data: Snapshot; onSettings(): void }) {
  const employee = data.role === 'employee'; const actual = employee ? data.budgets.memberUsedSats : data.budgets.companyUsedSats; const budgetLimit = employee ? data.budgets.memberLimitSats : data.organization.budget_sats;
  const showSamples = data.preview && !data.expenses.some(item => item.status === 'settled' && !item.is_fixture && item.budget_period === data.budgets.periodStart);
  const categories = ['Software', 'Operations', 'Travel', 'Events', 'Other'].map(category => ({ category, value: data.expenses.filter(item => item.category === category && (showSamples ? item.status === 'sample_paid' && item.created_at >= data.budgets.periodStart : item.status === 'settled' && !item.is_fixture && item.budget_period === data.budgets.periodStart)).reduce((sum, item) => sum + item.amount_sats, 0) }));
  const total = categories.reduce((sum, category) => sum + category.value, 0);
  return <><div className="budget-page-top"><section className="panel budget-main"><span className="section-kicker">{employee ? 'MY MONTHLY SPENDING LIMIT' : 'MONTHLY COMPANY BUDGET'}</span><div className="big-budget">{sats(budgetLimit)}<span>sats</span></div><Progress value={actual} maximum={budgetLimit} label="Approved spending committed" /><div className="budget-figures"><span>Committed<strong>{sats(actual)} sats</strong></span><span>Available<strong>{sats(budgetLimit - actual)} sats</strong></span><span>Per request<strong>{sats(data.organization.request_limit_sats)} sats</strong></span></div>{data.role === 'owner' && <button className="button secondary compact" onClick={onSettings}><SlidersHorizontal size={17} />Edit spending policy</button>}<p className="helper">{budgetPeriodHint}</p><p className="helper">Approved, in-progress, uncertain, and verified payments reserve budget. Sample rows do not consume a real spending limit.</p></section><section className="panel category-panel"><h2>{showSamples ? 'Sample paid expenses' : 'Verified paid expenses'}</h2><p>Spend by category</p><div className="category-chart">{categories.map(({ category, value }) => <div key={category}><span className={`category-dot category-${category.toLowerCase()}`} /><span>{category}</span><div className="category-bar"><span style={{ width: `${total ? value / total * 100 : 0}%` }} /></div><strong>{sats(value)}</strong></div>)}</div><span className="category-total">Total <strong>{sats(total)} sats</strong></span></section></div><section className="panel"><div className="panel-heading"><div><h2>Team spending limits</h2><p>Each member’s approved and verified spending this month.</p></div><UsersThree size={23} /></div><div className="member-budget-list">{data.members.filter(member => member.active && member.role !== 'viewer').map((member, index) => { const used = data.expenses.filter(item => !item.is_fixture && item.requester_id === member.id && (['approved', 'paying', 'unknown'].includes(item.status) || (item.status === 'settled' && item.budget_period === data.budgets.periodStart))).reduce((sum, item) => sum + item.amount_sats, 0); return <div key={member.id}><Avatar name={member.name} index={index} /><span><strong>{member.name}</strong><small>{roleLabel(member.role)}</small></span><div><Progress value={used} maximum={member.periodLimitSats} label={`${member.name} monthly spending`} /><span>{sats(used)} of {sats(member.periodLimitSats)} sats</span></div><strong>{Math.round(used / member.periodLimitSats * 100)}%</strong></div>; })}</div></section></>;
}
function Settings({ data, busy, onWallet, onSave, onExport, onDelete }: { data: Snapshot; busy: boolean; onWallet(): void; onSave(input: unknown): Promise<unknown>; onExport(): void; onDelete(): void }) {
  const [name, setName] = useState(data.organization.name); const [budget, setBudget] = useState(data.organization.budget_sats); const [limit, setLimit] = useState(data.organization.request_limit_sats);
  const owner = data.role === 'owner';
  return <><div className="settings-grid"><section className="panel settings-card"><div className="panel-heading"><div><h2>Company details</h2><p>The name and policy shared across your workspace.</p></div><Buildings size={23} /></div><form onSubmit={event => { event.preventDefault(); void onSave({ name, budgetSats: budget, requestLimitSats: limit }); }}><label>Workspace name<input value={name} maxLength={80} minLength={2} required disabled={!owner} onChange={event => setName(event.target.value)} /></label><label>Monthly company budget <span>sats</span><input type="number" value={budget} min={1} max={100000000} required disabled={!owner} onChange={event => setBudget(Number(event.target.value))} /></label><label>Maximum per request <span>sats</span><input type="number" value={limit} min={1} max={100000000} required disabled={!owner} onChange={event => setLimit(Number(event.target.value))} /></label><p className="helper">{budgetPeriodHint}</p><p className="helper">Limits are checked by the server before an approval. You cannot lower a budget below already committed spending.</p><button className="button primary" type="submit" disabled={!owner || busy}>{busy ? 'Saving…' : 'Save changes'}<Check size={16} /></button>{!owner && <p className="helper">Only the owner can change company settings.</p>}</form></section><div className="settings-side"><section className="panel wallet-setting-card"><span className="settings-icon"><Wallet size={25} /></span><h2>Company Lightning wallet</h2><p>{data.wallet.connected ? 'Your company wallet is connected and ready for invoice operations.' : 'Link the wallet your company already uses. Funds stay under your wallet provider’s control.'}</p><span className={`access-chip ${data.wallet.connected ? '' : 'disabled'}`}><span />{data.wallet.connected ? 'Connected' : 'Not connected'}</span><button className="button secondary full-width" onClick={onWallet}>{data.wallet.connected ? 'Manage connection' : 'Connect wallet'}<ArrowRight size={17} /></button></section><section className="security-card"><ShieldCheck size={27} /><h3>Two layers of control.</h3><p>GreyFinance checks team roles and independent approvals. Your wallet should also cap this connection’s permissions and spending.</p><span>No seed phrases. No master keys.</span></section></div></div>{owner && !data.preview && <section className="panel company-delete-panel" aria-labelledby="company-delete-heading"><div className="company-delete-copy"><span className="company-delete-icon" aria-hidden="true"><WarningCircle size={23} /></span><div><h2 id="company-delete-heading">Delete this company</h2><p>Permanently remove this workspace and its company records. Export your ledger before continuing.</p></div></div><div className="company-delete-actions"><button className="button secondary" onClick={onExport} disabled={busy}><DownloadSimple size={17} />Export ledger</button><button className="button danger-outline" onClick={onDelete} disabled={busy}>Delete company<ArrowRight size={17} /></button></div></section>}</>;
}

function DeleteCompanyDialog({ name, busy, error, onClose, onExport, onSubmit }: { name: string; busy: boolean; error: string; onClose(): void; onExport(): void; onSubmit(confirmation: string): Promise<unknown> }) {
  const [confirmation, setConfirmation] = useState('');
  const [downloadStarted, setDownloadStarted] = useState(false);
  const busyRef = useRef(busy); busyRef.current = busy;
  const dismiss = useCallback(() => { if (!busyRef.current) onClose(); }, [onClose]);
  const matches = confirmation === name;
  return <Dialog title="Delete this company?" description="This permanently removes the company from GreyFinance." onClose={dismiss}>
    <div className="company-delete-summary"><span className="company-delete-icon" aria-hidden="true"><WarningCircle size={25} /></span><h3>{name}</h3><p>Company settings, team access, expense requests, company receipts, and the audit trail will be removed. <strong>This cannot be undone.</strong></p></div>
    <div className="company-delete-export"><div><p>Keep a copy of any records you need.</p>{downloadStarted && <p className="company-delete-download-status" role="status">Ledger download started.</p>}</div><button className="button secondary" onClick={() => { onExport(); setDownloadStarted(true); }} disabled={busy}><DownloadSimple size={17} />Export ledger</button></div>
    <p className="company-delete-wallet-note">Your wallet funds stay with your wallet provider. GreyFinance disconnects the stored wallet connection; provider permissions and outstanding invoices remain. Your identity, sign-in, and memberships in other companies are kept.</p>
    <form className="company-delete-form" aria-busy={busy} onSubmit={event => { event.preventDefault(); if (matches && !busy) void onSubmit(confirmation); }}>
      <label htmlFor="delete-company-name">Confirm company name</label>
      <input id="delete-company-name" value={confirmation} required maxLength={80} autoComplete="off" spellCheck={false} disabled={busy} aria-describedby={`delete-company-name-help${error ? ' delete-company-error' : ''}`} onChange={event => setConfirmation(event.target.value)} />
      <p id="delete-company-name-help" className="helper">Type <strong>{name}</strong> exactly to confirm.</p>
      {error && <div id="delete-company-error" className="company-delete-error" role="alert"><WarningCircle size={19} /><span>{error}</span></div>}
      <p className="helper">Deletion is blocked while any company or owner-wallet payment is in progress or uncertain.</p>
      <div className="company-delete-form-actions"><button className="button secondary" type="button" disabled={busy} onClick={dismiss}>Keep company</button><button className="button danger" type="submit" disabled={!matches || busy}><WarningCircle size={17} />{busy ? 'Deleting company…' : 'Permanently delete company'}</button></div>
    </form>
  </Dialog>;
}

function RequestDialog({ preview, limit, busy, onClose, onSubmit }: { preview: boolean; limit: number; busy: boolean; onClose(): void; onSubmit(input: unknown): Promise<unknown> }) {
  const [title, setTitle] = useState(''); const [category, setCategory] = useState('Software'); const [invoice, setInvoice] = useState(''); const [sample, setSample] = useState(preview); const [amount, setAmount] = useState('15000');
  return <Dialog title="Request a company payment" description="Give finance a clear reason and the invoice to pay." onClose={onClose}><form onSubmit={event => { event.preventDefault(); void onSubmit({ title, category, bolt11: sample ? '' : invoice, ...(sample ? { previewAmountSats: Number(amount) } : {}) }); }}><label>What is this expense for?<input placeholder="e.g. Design tools for the team" minLength={3} maxLength={120} required value={title} onChange={event => setTitle(event.target.value)} /></label><label>Category<select value={category} onChange={event => setCategory(event.target.value)}>{['Software', 'Operations', 'Travel', 'Events', 'Other'].map(value => <option key={value}>{value}</option>)}</select></label>{preview && <div className="form-segment" aria-label="Request mode"><button type="button" className={sample ? 'active' : ''} onClick={() => setSample(true)}>Sample request</button><button type="button" className={!sample ? 'active' : ''} onClick={() => setSample(false)}>Real Lightning invoice</button></div>}{sample ? <><label>Sample amount <span>sats</span><input type="number" min={1} max={limit} required value={amount} onChange={event => setAmount(event.target.value)} /></label><div className="alert"><Info size={20} /><span>This creates a sample approval request. It cannot send a wallet payment.</span></div></> : <><label>Lightning invoice<textarea placeholder="lnbc…" rows={4} maxLength={6000} required value={invoice} onChange={event => setInvoice(event.target.value)} spellCheck={false} /></label><p className="helper">The amount and expiry are read from the invoice. Maximum {sats(limit)} sats per request. Ask the recipient for a fresh fixed-amount invoice.</p></>}<button className="button primary full-width" type="submit" disabled={busy}><Receipt size={17} />{busy ? 'Submitting…' : 'Submit for approval'}</button></form></Dialog>;
}
function WalletDialog({ connected, network, localLab, isOwner, busy, onClose, onConnect, onTestWallet, onDisconnect }: { connected: boolean; network?: string; localLab: boolean; isOwner: boolean; busy: boolean; onClose(): void; onConnect(uri: string): Promise<unknown>; onTestWallet(): Promise<unknown>; onDisconnect(): Promise<unknown> }) {
  const [uri, setUri] = useState('');
  const [confirmDisconnect, setConfirmDisconnect] = useState(false);
  return <Dialog title="Your company wallet" description="A secure connection to the wallet you control." onClose={onClose}>
    <div className="wallet-intro"><span><Wallet size={31} weight="duotone" /></span><div><strong>Nostr Wallet Connect</strong><small>{isTestNetwork(network) ? 'Private Bitcoin test network' : 'Company-controlled Lightning payments'}</small></div><span className={`access-chip ${connected ? '' : 'disabled'}`}><span />{connected ? 'Connected' : 'Ready to link'}</span></div>
    {!isOwner ? <div className="alert"><ShieldCheck size={21} /><span>Only your company’s owner can connect or disconnect its wallet.</span></div> : localLab ? <>
      <section className="test-wallet-option"><div><Lightning size={24} weight="fill" /><span><strong>Try the local Lightning lab</strong><small>Real Lightning payments on a private Bitcoin test network. Test sats have no live value.</small></span></div><button className="button primary full-width" disabled={busy} onClick={() => void onTestWallet()}>{busy ? 'Connecting test wallet…' : 'Use Lightning test wallet'}<ArrowRight size={17} /></button></section>
      <p className="helper">This preview uses test wallets only. To connect your own company wallet, sign out of the preview and sign in with your Nostr identity.</p>
    </> : <>
      <form onSubmit={event => { event.preventDefault(); const value = uri; setUri(''); void onConnect(value); }}><label>{connected ? 'Replace wallet connection' : 'Wallet connection URI'}<input type="password" autoComplete="off" spellCheck={false} placeholder="nostr+walletconnect://…" value={uri} onChange={event => setUri(event.target.value)} required maxLength={8000} /></label><p className="helper">Create a restricted connection in your wallet. Allow invoice creation and lookup; add payment permission only if your company needs expense payments. Cap its spending at the provider.</p><button className="button primary full-width" type="submit" disabled={busy || !uri}><Lightning size={18} />{busy ? 'Checking connection…' : connected ? 'Replace connection' : 'Connect company wallet'}</button></form>
      {connected && <div className="disconnect-block">{confirmDisconnect ? <><p>This removes GreyFinance’s stored connection. Revoke its permissions in the wallet provider as well.</p><button className="button danger full-width" disabled={busy} onClick={() => void onDisconnect()}>Disconnect this wallet</button></> : <button className="text-button danger-text" onClick={() => setConfirmDisconnect(true)}>Disconnect wallet</button>}</div>}
    </>}
    <div className="wallet-promise"><ShieldCheck size={19} /><span>Never enter a seed phrase. Your delegated connection is encrypted on the server and kept out of browser storage.</span></div>
  </Dialog>;
}
function ReceiveDialog({ initial, canReceive, walletConnected, busy, onClose, onWallet, onCopy, onCreate, onVerify, onSettled }: { initial?: Invoice; canReceive: boolean; walletConnected: boolean; busy: boolean; onClose(): void; onWallet(): void; onCopy(text: string): void; onCreate(input: { amountSats: number; description: string }): Promise<Invoice | undefined>; onVerify(hash: string): Promise<Invoice>; onSettled(): void }) {
  const [invoice, setInvoice] = useState(initial); const [amount, setAmount] = useState('1000'); const [description, setDescription] = useState('Company payment'); const [qr, setQr] = useState(''); const [verificationError, setVerificationError] = useState('');
  useEffect(() => { if (!invoice) return; let ignore = false; void QRCode.toDataURL(`lightning:${invoice.bolt11}`, { width: 260, margin: 2, color: { dark: '#163c32', light: '#fffef9' }, errorCorrectionLevel: 'M' }).then(value => { if (!ignore) setQr(value); }); return () => { ignore = true; }; }, [invoice?.bolt11]);
  useEffect(() => { if (!invoice || invoice.state !== 'pending') return; let ignore = false; const timer = setInterval(() => { void onVerify(invoice.paymentHash).then(current => { if (ignore) return; setInvoice(current); setVerificationError(''); if (current.state === 'settled') onSettled(); }).catch(() => { if (!ignore) setVerificationError('The wallet is temporarily unavailable. Your invoice is still saved.'); }); }, 5000); return () => { ignore = true; clearInterval(timer); }; }, [invoice?.paymentHash, invoice?.state]);
  return <Dialog title={invoice ? 'Receive company payment' : 'Create a receive invoice'} description="A Lightning invoice, directly from your company wallet." onClose={onClose}>{invoice ? <div className="receive-invoice"><Status state={invoice.state} label={invoice.state === 'pending' ? 'Awaiting payment' : undefined} /><h3>{sats(invoice.amountSats)} <span>sats</span></h3><p>{invoice.description}</p>{qr && <img className="invoice-qr" src={qr} alt={`Lightning payment QR for ${invoice.amountSats} sats`} />}<div className="invoice-string"><code>{invoice.bolt11.slice(0, 34)}…{invoice.bolt11.slice(-16)}</code><button className="icon-button" onClick={() => onCopy(invoice.bolt11)} aria-label="Copy Lightning invoice"><Copy size={20} /></button></div><button className="button primary full-width" onClick={() => onCopy(invoice.bolt11)}><Copy size={17} />Copy invoice</button><details className="full-invoice"><summary>View full invoice</summary><textarea aria-label="Full Lightning invoice" readOnly rows={4} value={invoice.bolt11} onFocus={event => event.target.select()} /></details>{invoice.state === 'settled' && <ProofReceipt paymentHash={invoice.paymentHash} preimage={invoice.preimage} walletFingerprint={invoice.walletFingerprint} settledAt={invoice.settledAt} />}<p className="helper">{invoice.state === 'settled' ? 'Payment has been verified against your company wallet.' : invoice.state === 'expired' ? 'This invoice has expired. Close it and create a new one.' : `Waiting for verified payment · expires ${fullDate(invoice.expiresAt)}`}</p>{verificationError && <div className="alert" role="status"><WarningCircle size={17} /><span>{verificationError}</span></div>}</div> : !walletConnected ? <Empty icon={<Wallet size={30} />} title="Connect your company wallet first" copy="Receive invoices need a real wallet connection. No invoice is simulated." action={<button className="button primary" onClick={onWallet}>Connect wallet <ArrowRight size={17} /></button>} /> : !canReceive ? <div className="alert"><ShieldCheck size={22} /><span>Ask the owner or a finance member to create company receive invoices.</span></div> : <form onSubmit={event => { event.preventDefault(); void onCreate({ amountSats: Number(amount), description }).then(result => { if (result) setInvoice(result); }); }}><label>Amount <span>sats</span><input type="number" min={1} max={100000000} required value={amount} onChange={event => setAmount(event.target.value)} /></label><label>Payment reference<input minLength={3} maxLength={160} required value={description} onChange={event => setDescription(event.target.value)} /></label><div className="alert"><ShieldCheck size={20} /><span>GreyFinance will record payment only after wallet verification. A screenshot or a customer’s message is not payment proof.</span></div><button className="button primary full-width" type="submit" disabled={busy}><ArrowDownLeft size={18} />{busy ? 'Creating invoice…' : 'Create Lightning invoice'}</button></form>}</Dialog>;
}
function ExpenseDialog({ item, data, busy, onClose, onCopy, onAction, onPay, onFinance }: { item: Expense; data: Snapshot; busy: boolean; onClose(): void; onCopy(text: string): void; onAction(action: 'approve' | 'reject' | 'reconcile', reason?: string): void; onPay(): void; onFinance(): void }) {
  const [declining, setDeclining] = useState(false); const [reason, setReason] = useState('');
  const reviewer = ['owner', 'finance'].includes(data.role); const own = item.requester_id === data.currentUser.id;
  return <Dialog title="Expense request" description={`Requested ${fullDate(item.created_at)}`} onClose={onClose}><div className="expense-detail"><div className="expense-detail-top"><span className={`category-icon category-${item.category.toLowerCase()}`}><Receipt size={24} /></span><Status state={item.status} sample={Boolean(item.is_fixture)} /></div><h3>{item.title}</h3><div className="detail-amount">{sats(item.amount_sats)} <span>sats</span></div><div className="detail-grid"><span>Requested by<strong>{item.requester_name ?? 'Team member'}</strong></span><span>Category<strong>{item.category}</strong></span><span>Approver<strong>{item.approver_name ?? 'Awaiting review'}</strong></span><span>Invoice expiry<strong>{item.is_fixture ? 'Sample request' : fullDate(item.expires_at)}</strong></span></div>{item.is_fixture ? <div className="alert"><Info size={19} /><span>This is a sample expense. You can review it, but no wallet payment can be made.</span></div> : <div className="payment-reference"><span>Payment hash</span><code>{item.payment_hash}</code><button className="text-button" onClick={() => onCopy(item.payment_hash)}><Copy size={14} />Copy reference</button></div>}{item.failure_code && <div className="alert"><WarningCircle size={19} /><span>{item.status === 'unknown' ? 'The payment result is uncertain. Keep the budget reserved and check the wallet status; no repeat payment is allowed.' : item.failure_code}</span></div>}{item.status === 'pending' && reviewer && !own && <>{declining ? <form onSubmit={event => { event.preventDefault(); onAction('reject', reason); }}><label>Reason for declining<input value={reason} onChange={event => setReason(event.target.value)} minLength={3} maxLength={160} required placeholder="Help the requester understand why" /></label><div className="dialog-actions"><button className="button secondary" type="button" onClick={() => setDeclining(false)}>Go back</button><button className="button danger" type="submit" disabled={busy}>Decline request</button></div></form> : <div className="dialog-actions"><button className="button secondary" disabled={busy} onClick={() => setDeclining(true)}>Decline</button><button className="button primary" disabled={busy} onClick={() => onAction('approve')}><Check size={18} />{busy ? 'Reviewing…' : 'Approve request'}</button></div>}</>}{item.status === 'pending' && own && <div className="self-approval-note"><ShieldCheck size={19} /><p>A different owner or finance member must approve your request.</p>{data.preview && data.role !== 'finance' && <button className="text-button" onClick={onFinance}>Try Finance view <ArrowRight size={14} /></button>}</div>}{item.status === 'approved' && reviewer && !own && <button className="button primary full-width" disabled={busy || Boolean(item.is_fixture)} onClick={onPay}><Lightning size={18} />{item.is_fixture ? 'Sample approved · no funds moved' : `Review payment · ${sats(item.amount_sats)} sats`}</button>}{['unknown', 'paying'].includes(item.status) && reviewer && <button className="button primary full-width" disabled={busy} onClick={() => onAction('reconcile')}><ShieldCheck size={18} />{busy ? 'Checking wallet…' : 'Check verified payment status'}</button>}{item.status === 'settled' && <ProofReceipt paymentHash={item.payment_hash} preimage={item.preimage} walletFingerprint={item.wallet_fingerprint} settledAt={item.settled_at} />}</div></Dialog>;
}
function MemberDialog({ member, isOwner, busy, onClose, onSubmit }: { member?: Member; isOwner: boolean; busy: boolean; onClose(): void; onSubmit(input: unknown): Promise<unknown> }) {
  const [name, setName] = useState(member?.name ?? ''); const [pubkey, setPubkey] = useState(''); const [role, setRole] = useState(member?.role ?? 'employee'); const [limit, setLimit] = useState(String(member?.periodLimitSats ?? 75000)); const [active, setActive] = useState(member?.active !== 0);
  return <Dialog title={member ? 'Member permissions' : 'Bring someone into the team'} description={member ? member.name : 'Access is tied to a Nostr identity. No email invitation is sent.'} onClose={onClose}>{!isOwner ? <div className="alert"><ShieldCheck size={21} /><span>Only the owner can manage team permissions.</span></div> : <form onSubmit={event => { event.preventDefault(); void onSubmit(member ? { role, periodLimitSats: Number(limit), active } : { name, pubkey, role, periodLimitSats: Number(limit) }); }}>{!member && <><label>Team member name<input minLength={2} maxLength={60} value={name} onChange={event => setName(event.target.value)} required /></label><label>Nostr public key<input placeholder="npub1… or 64-character public key" value={pubkey} maxLength={90} onChange={event => setPubkey(event.target.value)} spellCheck={false} required /></label></>}<label>Workspace role<select value={role} onChange={event => setRole(event.target.value)}>{['employee', 'finance', 'viewer'].map(value => <option key={value} value={value}>{roleLabel(value)}</option>)}</select></label><label>Monthly spending limit <span>sats</span><input type="number" min={1} max={100000000} value={limit} onChange={event => setLimit(event.target.value)} required /></label>{member && <label className="checkbox-label"><input type="checkbox" checked={active} onChange={event => setActive(event.target.checked)} /><span>Allow workspace access</span></label>}<div className="alert"><ShieldCheck size={19} /><span>{role === 'finance' ? 'Finance can approve other members’ requests and execute company payments. Your wallet spending permissions still apply.' : role === 'viewer' ? 'Viewers can read company records but cannot create or approve payments.' : 'Employees can submit requests and track their own spending. They cannot approve or execute payments.'}</span></div><button className="button primary full-width" disabled={busy} type="submit"><UsersThree size={18} />{busy ? 'Saving access…' : member ? 'Save permissions' : 'Add member access'}</button></form>}</Dialog>;
}
function WorkspaceDialog({ busy, onClose, onSubmit }: { busy: boolean; onClose(): void; onSubmit(input: unknown): Promise<unknown> }) {
  const [name, setName] = useState(''); const [ownerName, setOwnerName] = useState(''); const [budget, setBudget] = useState('250000'); const [limit, setLimit] = useState('100000');
  return <Dialog title="Create your company workspace" description="A shared place for your company’s Bitcoin payments." onClose={onClose}><form onSubmit={event => { event.preventDefault(); void onSubmit({ name, ownerName, budgetSats: Number(budget), requestLimitSats: Number(limit) }); }}><label>Company name<input placeholder="Your studio, business, or team" minLength={2} maxLength={80} required value={name} onChange={event => setName(event.target.value)} /></label><label>Your name<input minLength={2} maxLength={60} required value={ownerName} onChange={event => setOwnerName(event.target.value)} /></label><div className="form-columns"><label>Monthly budget <span>sats</span><input type="number" min={1} max={100000000} value={budget} onChange={event => setBudget(event.target.value)} required /></label><label>Per-request limit <span>sats</span><input type="number" min={1} max={100000000} value={limit} onChange={event => setLimit(event.target.value)} required /></label></div><p className="helper">You can own one company and join others.</p><p className="helper">You’ll be the owner. After creating the workspace, connect your wallet and add a finance member for independent approvals.</p><button className="button primary full-width" type="submit" disabled={busy}><Buildings size={18} />{busy ? 'Creating…' : 'Create workspace'}</button></form></Dialog>;
}
